__NUXT_JSONP__("/ru/how-to-apply/student-visa-f1/change-of-status", {data:[{details:{slug:"ru",pageTitle:"Если вы меняете статус | Mentor Language Institute",pageDescription:"Спасибо за Ваш интерес к MLI. Эта страница для тех кто находится в США на данный момент без студенческой визы и хотели бы поменять свой статус на F1 статус.",title:"Если вы меняете статус",image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fchange-of-status.jpg",subtitle:["Спасибо за Ваш интерес к MLI. \u003Cbr \u002F\u003EЭта страница для тех кто находится в США на данный момент без студенческой визы и хотели бы поменять свой статус на F1 статус.","If you wish to apply please proceed:"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fapply-now-ru.png",link:"\u002Fru\u002Fadmission"}},applicationSteps:{title:"Шаги подачи заявки",description:["Шаги подачи заявки зависят от страны заявителя, национальности, курса, визы и тд. Наши стаффы будут рады рассказать вам о шагах смены статуса на основе вашей индивидуальной заявки"]},needHelp:{title:"Нужна помощь? Спросите нас!",description:["Правила смены статуса а также шаги подачи заявки различаются на основе того какой у вас сейчас статус.\u003Cbr \u002F\u003EЕсли вам нужно разъяснение перед подачей заявки, пожалуйста, свяжитесь с нами. Наши сотрудники говорят на 8 разных языках."]},contactUs:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fcontact-us-ru.jpg",link:"\u002Fru\u002Fcontact",title:"Связаться с нами",lists:[{campus:"＜ВЕСТВУД КАМПУС＞",address:"10880 Вилшер Бул-р., Офис #122, Лос Анджелес, Калифорния 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"＜ГОЛЛИВУД КАМПУС＞",address:"7080 Голливуд Бул-р., Офис 314 Лос-Анджелес, Калифорния 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fchange-of-status",path:"\u002Fchange-of-status\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:28.795Z",updatedAt:"2025-05-26T12:06:27.714Z"}}],fetch:{},mutations:void 0});